pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 newMinSum) internal {
        uint256 balanceBefore = address(c).balance;
        try c.SetMinSum(newMinSum) {} catch { return; }
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore);
    }

    function testFuzz_run(uint256 newMinSum) public {
        _run(newMinSum);
    }

    receive() external payable {}
}
